54	architecture rtl of cl_fix_round_tb is
55	
56	    constant datapath_c         : string := tb_path(runner_cfg) & "../bittrue/cosim/cl_fix_round/data/";
57	    
58	    -- Formats
59	    constant a_fmt_c            : FixFormatArray_t := cl_fix_read_format_file(datapath_c & "a_fmt.txt");
60	    constant r_fmt_c            : FixFormatArray_t := cl_fix_read_format_file(datapath_c & "r_fmt.txt");
61	    
62	    -- Rounding modes
63	    constant rnd_c              : integer_vector := read_file(datapath_c & "rnd.txt");
64	    
65	    constant test_count_c       : positive := a_fmt_c'length;
66	    constant reg_mode_count_c   : positive := 1 + RegisterMode_t'pos(RegisterMode_t'high);  -- In VHDL-2019: RegisterMode_t'length.
67	    
68	    signal clk                  : std_logic := '0';
69	    
70	    signal finished             : std_logic_vector(0 to test_count_c-1) := (others => '0');
71	    
72	    -- Helper function for printing error info
73	    function str(x : integer; x_fmt : FixFormat_t) return string is
74	    begin
75	        return to_string(cl_fix_to_real(cl_fix_from_integer(x, x_fmt), x_fmt));
76	    end function;
77	    
78	begin
79	    
80	    test_runner_watchdog(runner, 100 ms);
81	    
